  // ---------- Dibujos nuevos (contenido ampliado 29-10-2026): cada lámina y pregunta con su propio dibujo
  const PS = () => window.__ZPS || 1;
  const hd = (x, y, pose, s, flip) => { const P = POSES[pose || 'stand'] || POSES.stand, k = (s || 1) * PS(); return [x + P.head[0] * k * (flip ? -1 : 1), y + P.head[1] * k, 9.5 * k]; };
  const lejos = g => { ZM = false; Object.keys(SND).forEach(j => delete SND[j]); return g; };
  const globo = (x, y, t, hx, hy, c = '#fff', z = 9.5) => { const w = Math.round(t.length * z * .56 + 14); return `<path d="M${hx},${hy} L${x - 5},${y + 8} L${x + 6},${y + 8}z" fill="${c}" stroke="#455A64"/><rect x="${x - w / 2}" y="${y - 12}" width="${w}" height="22" rx="9" fill="${c}" stroke="#455A64"/><rect x="${x - 6}" y="${y + 6}" width="12" height="3" fill="${c}"/>` + T0(x, y + 3, t, z, '#263238'); };
  const tablilla = (x, y, s = 1) => sc(`<rect x="${x}" y="${y}" width="14" height="18" rx="1.5" fill="#8D6E63"/><rect x="${x + 2}" y="${y + 3}" width="10" height="13" fill="#fff"/>` + [0, 1, 2].map(i => `<line x1="${x + 3.5}" y1="${y + 6 + i * 3.5}" x2="${x + 10.5}" y2="${y + 6 + i * 3.5}" stroke="#90A4AE" stroke-width="1"/>`).join('') + `<rect x="${x + 4}" y="${y - 1}" width="6" height="3" rx="1" fill="#B0BEC5"/>`, x, y, s);
  const triangulo = (x, y, s = 1) => `<path d="M${x},${y - 16 * s} L${x + 10 * s},${y} H${x - 10 * s}Z" fill="#FFCDD2" fill-opacity=".35" stroke="#D50000" stroke-width="${3 * s}" stroke-linejoin="round"/>`;
  const cuna = (x, y, s = 1) => `<path d="M${x},${y} l${9 * s},${-9 * s} v${9 * s}z" fill="#FBC02D" stroke="#795548"/>`;
  const arbol = (x, y, s = 1) => `<rect x="${x - 4 * s}" y="${y - 50 * s}" width="${8 * s}" height="${50 * s}" fill="#6D4C41"/><circle cx="${x}" cy="${y - 62 * s}" r="${24 * s}" fill="#2E7D32"/><circle cx="${x - 18 * s}" cy="${y - 50 * s}" r="${16 * s}" fill="#388E3C"/><circle cx="${x + 18 * s}" cy="${y - 52 * s}" r="${17 * s}" fill="#33691E"/>`;
